#include "api_grid_test_common.h"

using namespace api_grid_test;

namespace {

// Global host reference for a matrix generated by base_value(i,j).
inline std::vector<Complex> make_global(int m, int n, Complex (*value)(int, int))
{
    std::vector<Complex> G(static_cast<size_t>(m) * n);
    for(int i = 0; i < m; ++i)
        for(int j = 0; j < n; ++j)
            G[static_cast<size_t>(i) * n + j] = value(i, j);
    return G;
}

// Apply the pivot permutation to a global host matrix, mirroring plapiv:
// P(k) swaps row/col k with row/col g_ipiv[k]-1; forward applies k ascending,
// backward descending.  Returns the permuted global matrix.
inline std::vector<Complex> apply_pivots_host(const std::vector<Complex>& G,
                                              int m, int n, char direc, char rowcol,
                                              const std::vector<int>& g_ipiv)
{
    std::vector<Complex> R = G;
    const int begin = (direc == 'F') ? 0 : m - 2;
    const int end   = (direc == 'F') ? m - 1 : -1;
    const int step  = (direc == 'F') ? 1 : -1;
    for(int k = begin; k != end; k += step){
        const int target = g_ipiv[k] - 1;
        if(target == k) continue;
        if(rowcol == 'C'){
            for(int i = 0; i < m; ++i)
                std::swap(R[static_cast<size_t>(i) * n + k],
                          R[static_cast<size_t>(i) * n + target]);
        }else{
            for(int j = 0; j < n; ++j)
                std::swap(R[static_cast<size_t>(k) * n + j],
                          R[static_cast<size_t>(target) * n + j]);
        }
    }
    return R;
}

// Global pivot vector for the fixed permutation that swaps (0,m-1) and
// (1,m-2); the rest are identity.  g_ipiv[k] is the 1-based target for step k.
inline std::vector<int> make_g_ipiv(int m)
{
    std::vector<int> g_ipiv(m);
    for(int k = 0; k < m; ++k){
        if(k == 0)      g_ipiv[k] = m;
        else if(k == 1) g_ipiv[k] = m - 1;
        else            g_ipiv[k] = k + 1;
    }
    return g_ipiv;
}

// Fill the distributed ipiv array from the global pivot vector: the local
// entry on the owning process holds g_ipiv[k] (1-based) for its global row k.
inline void fill_ipiv(std::vector<int>& ipiv, const ddla::DdlaDesc& desc,
                      const std::vector<int>& g_ipiv)
{
    for(int iloc = 0; iloc < desc.m_loc(); ++iloc){
        const int k = desc.indx_l2g_r(iloc);
        ipiv[iloc] = g_ipiv[k];
    }
}

inline void check_one_case(const ddla::DdlaHandle_t& handle, const ddla::DdlaDesc& desc,
                           int m, int n, char direc, char rowcol,
                           Complex (*value)(int, int), double tol)
{
    const std::string name = std::string("plapiv(") + direc + "," + rowcol + ",C)";
    const std::vector<int> g_ipiv = make_g_ipiv(m);
    std::vector<int> ipiv(desc.m_loc(), 0);
    fill_ipiv(ipiv, desc, g_ipiv);

    const auto h_A = make_local<Complex>(desc, value);
    DeviceBuffer<Complex> d_A(handle, h_A.size());
    upload(handle, d_A.ptr, h_A);
    check_ddla_sync(handle);

    ddla::plapiv(direc, rowcol, 'C', m, n, d_A.ptr, desc, ipiv.data(), desc, nullptr);
    auto out = download(handle, d_A.ptr, h_A.size());

    const auto G = make_global(m, n, value);
    const auto R = apply_pivots_host(G, m, n, direc, rowcol, g_ipiv);

    double err = 0.0;
    for(int jloc = 0; jloc < desc.n_loc(); ++jloc){
        const int j = desc.indx_l2g_c(jloc);
        if(j >= n) continue;
        for(int iloc = 0; iloc < desc.m_loc(); ++iloc){
            const int i = desc.indx_l2g_r(iloc);
            if(i >= m) continue;
            err = std::max(err, static_cast<double>(
                std::abs(out[iloc + jloc * desc.lld()] - R[static_cast<size_t>(i) * n + j])));
        }
    }
    require_close(handle, name, err, tol);
}

} // namespace

void check_plapiv(const ddla::DdlaHandle_t& handle, const Shape& base)
{
    const int nb = base.nb;
    int nprows = 0, npcols = 0;
    ddla_get_grid_dims(handle, nprows, npcols);
    // Use a square matrix so the pivot count m equals both the number of rows
    // and columns: the pivot vector (distributed by rows of the descriptor)
    // has one entry per pivot in both the 'R' and 'C' cases.
    const int m = round_up_for_grid(base.m, nb, std::max(nprows, npcols));
    ddla::DdlaDesc desc(handle);
    desc.init(m, m, nb, nb, 0, 0);

    auto value = [](int i, int j){ return Complex(10.0 * i + j, -0.5 * i + 0.25 * j); };

    // (direc, rowcol, m-pivots, n-segment)
    check_one_case(handle, desc, m, m, 'F', 'R', value, 1e-12);
    check_one_case(handle, desc, m, m, 'B', 'R', value, 1e-12);
    check_one_case(handle, desc, m, m, 'F', 'C', value, 1e-12);
    check_one_case(handle, desc, m, m, 'B', 'C', value, 1e-12);
}

int main(int argc, char** argv)
{
    return run_grid_test(argc, argv, "test_api_grid_plapiv", check_plapiv);
}
